from abc import ABC, abstractmethod
import csv
from dataclasses import dataclass, replace
from enum import Enum, auto
import io


class DomainError(Exception):
    pass


class UnknownStatusError(DomainError):
    pass


class InvalidTransitionError(DomainError):
    pass


class Status(Enum):
    ACTIVE = auto()
    SUSPENDED = auto()
    GRADUATED = auto()


@dataclass(frozen=True)
class StudentProfile:
    student_id: str
    name: str
    status: Status = Status.ACTIVE

    def __post_init__(self) -> None:
        object.__setattr__(self, "student_id", self.student_id.strip())
        object.__setattr__(self, "name", self.name.strip())
        if not self.student_id or not self.name:
            raise ValueError("student_id and name cannot be blank")
        if not isinstance(self.status, Status):
            raise TypeError("status must be Status")


ALLOWED = {
    Status.ACTIVE: {Status.SUSPENDED, Status.GRADUATED},
    Status.SUSPENDED: {Status.ACTIVE, Status.GRADUATED},
    Status.GRADUATED: set(),
}


def parse_status(text: str) -> Status:
    if not isinstance(text, str):
        raise TypeError("status text must be str")
    try:
        return Status[text.strip().upper()]
    except KeyError as error:
        raise UnknownStatusError(f"unknown status: {text!r}") from error


def move_to(profile: StudentProfile, target: Status) -> StudentProfile:
    if not isinstance(target, Status):
        raise TypeError("target must be Status")
    if target is profile.status:
        return profile
    if target not in ALLOWED[profile.status]:
        raise InvalidTransitionError(
            f"cannot move from {profile.status.name} to {target.name}"
        )
    return replace(profile, status=target)


class ProfileFormatter(ABC):
    @abstractmethod
    def format(self, profiles: list[StudentProfile]) -> str:
        """Return a report for profiles."""

    def checked(self, profiles: list[StudentProfile]) -> list[StudentProfile]:
        if not isinstance(profiles, list):
            raise TypeError("profiles must be list")
        if not all(isinstance(item, StudentProfile) for item in profiles):
            raise TypeError("every item must be StudentProfile")
        return profiles


class TextFormatter(ProfileFormatter):
    def format(self, profiles: list[StudentProfile]) -> str:
        profiles = self.checked(profiles)
        if not profiles:
            return "No profiles"
        return "\n".join(
            f"{item.student_id} | {item.name} | {item.status.name}"
            for item in profiles
        )


class CsvFormatter(ProfileFormatter):
    def format(self, profiles: list[StudentProfile]) -> str:
        profiles = self.checked(profiles)
        stream = io.StringIO(newline="")
        writer = csv.writer(stream, lineterminator="\n")
        writer.writerow(["student_id", "name", "status"])
        writer.writerows(
            (item.student_id, item.name, item.status.name) for item in profiles
        )
        return stream.getvalue()


def render(formatter: ProfileFormatter, profiles: list[StudentProfile]) -> str:
    if not isinstance(formatter, ProfileFormatter):
        raise TypeError("formatter must inherit ProfileFormatter")
    profiles = formatter.checked(profiles)
    return formatter.format(sorted(profiles, key=lambda item: item.student_id))


def expect(error_type: type[BaseException], action) -> BaseException:
    try:
        action()
    except error_type as error:
        return error
    raise AssertionError(f"expected {error_type.__name__}")


def run_checks() -> None:
    amy = StudentProfile(" S02 ", " Amy ")
    bo = StudentProfile("S01", "Bo", parse_status(" suspended "))
    graduated = move_to(amy, Status.GRADUATED)
    assert amy.status is Status.ACTIVE
    assert graduated.status is Status.GRADUATED
    assert move_to(graduated, Status.GRADUATED) is graduated

    text = render(TextFormatter(), [graduated, bo])
    assert text == "S01 | Bo | SUSPENDED\nS02 | Amy | GRADUATED"
    csv_text = render(CsvFormatter(), [graduated, bo])
    assert csv_text == (
        "student_id,name,status\n"
        "S01,Bo,SUSPENDED\n"
        "S02,Amy,GRADUATED\n"
    )
    assert render(TextFormatter(), []) == "No profiles"

    unknown = expect(UnknownStatusError, lambda: parse_status("paused"))
    assert isinstance(unknown.__cause__, KeyError)
    expect(InvalidTransitionError, lambda: move_to(graduated, Status.ACTIVE))
    expect(ValueError, lambda: StudentProfile("", "Bo"))
    expect(TypeError, lambda: render(object(), []))
    expect(TypeError, lambda: render(TextFormatter(), ["bad"]))


if __name__ == "__main__":
    run_checks()
    print("weekend-status-report checks: OK")

